"""Publish a synchronized comparison UI for the two upper-mid supplements."""
from pathlib import Path
import json

ROOT = Path(__file__).resolve().parents[2]
PUBLIC = ROOT / 'docs/experiments/20261008-iphone-km184-public'
payload = json.loads((PUBLIC / 'upper-mid-supplement-browser.json').read_text())
data = json.dumps(payload, ensure_ascii=False, separators=(',', ':'))
page = r'''<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>iPhone·S21 중고역 보완 필터 비교</title>
<style>:root{font-family:system-ui,-apple-system,sans-serif;color:#1a303a;background:#f5f8f9}body{margin:0}main{max-width:1290px;margin:auto;padding:20px}a{color:#087e8b}nav{display:flex;gap:15px;flex-wrap:wrap}h1{font-size:clamp(1.6rem,2.8vw,2.35rem)}h2{font-size:1.28rem}p{line-height:1.55}.lead{background:#eaf5f4;border-left:5px solid #087e8b;padding:14px 18px;border-radius:7px}.summary{display:flex;gap:10px;flex-wrap:wrap}.metric{background:white;border:1px solid #d5e0e4;border-radius:9px;padding:11px 16px}.layout{display:grid;grid-template-columns:205px minmax(0,1fr);gap:18px}.side{position:sticky;top:14px;align-self:start;display:grid;gap:8px}button{font:inherit;border:1px solid #bccdd2;background:#fff;color:#233f49;border-radius:8px;padding:10px;cursor:pointer;text-align:left}button[aria-selected=true],button[aria-pressed=true]{color:#fff;background:#087e8b;border-color:#087e8b}.devices{display:flex;gap:7px;margin:10px 0}.devices button{min-width:90px;text-align:center}.chart{background:#fff;border:1px solid #d2dfe3;border-radius:9px;padding:10px;overflow:auto}svg{width:100%;min-width:600px}.table-wrap{overflow:auto;background:#fff;border:1px solid #d5e0e4;border-radius:9px}table{border-collapse:collapse;width:100%;min-width:640px}th,td{text-align:left;padding:9px;border-bottom:1px solid #e1e8eb}th{background:#eaf1f3}.transport{position:sticky;top:0;z-index:5;background:#eaf3f4;border:1px solid #c5d7db;border-radius:9px;padding:9px;display:flex;gap:10px;align-items:center}.transport input{flex:1}.versions{display:grid;gap:12px;margin-top:13px}.version{background:white;border:1px solid #d5e0e4;border-radius:10px;padding:12px}.version h3{margin:0 0 8px;font-size:1.1rem}.version button{margin-top:8px}.image-row{display:grid;grid-template-columns:1fr 1fr;gap:8px}.spec{position:relative;cursor:pointer;background:#edf1f2;line-height:0}.spec img{width:100%;aspect-ratio:470/240;display:block}.cursor{position:absolute;left:0;top:0;bottom:0;width:2px;background:#33e6ed;box-shadow:0 0 1px #003a40;pointer-events:none}.axis{display:flex;justify-content:space-between;color:#60747d;font-size:.83rem}.note{font-size:.9rem;color:#526b75}@media(max-width:850px){.layout{grid-template-columns:1fr}.side{position:static;display:flex;overflow:auto}.side button{min-width:145px}.image-row{grid-template-columns:1fr}}</style>
<main><nav><a href="october-four-device-eq.html">네 기기 원래 비교</a><a href="upper-band-residual-qc.html">중고역 잔차 근거</a><a href="index.html">비교 홈</a></nav><h1>iPhone·S21 중고역 보완 필터</h1>
<p class="lead">1–2kHz를 통째로 누르는 후보와, <b>부족한 약 1.4–1.5kHz를 보충하고 과다한 약 2–2.5kHz를 누르는 후보</b>를 기존 필터 뒤에 실제로 적용했습니다. 사용자가 들은 날카로움이 전체 대역 과다 때문이라는 가정은 수치와 맞지 않습니다. 아래에서 같은 순간을 바로 전환해 비교할 수 있습니다.</p>
<div class="summary" id="summary"></div><h2>실제 필터 응답</h2><p>기존 필터에 보완 단을 더한 전체 응답입니다. 모든 비교에서 저역 및 기존 필터는 고정했습니다.</p><div class="chart"><svg id="response" viewBox="0 0 850 260" role="img" aria-label="기존, 전체 감쇠, 잔차 기반 필터의 주파수 응답"></svg></div>
<h2>주법별 같은 시각 비교</h2><p>왼쪽에서 주법을 선택하고 기기를 바꾸세요. 스펙트로그램을 누르거나 공통 위치 막대를 움직이면 모든 버전의 재생 위치가 같아집니다. 두 이미지는 각각 스펙트로그램과 KM184 대비 잔차(회색은 약한/미관측 부분)입니다.</p>
<div class="layout"><div class="side" id="groups"></div><section><div class="devices" id="devices"></div><p id="selection"></p><div class="transport"><button type="button" id="toggle">재생 / 일시정지</button><input id="seek" type="range" min="0" max="5" step="0.01" value="0" aria-label="공통 재생 위치"><span id="time">0.0 / 5.0초</span></div><div class="versions" id="versions"></div></section></div>
<h2>목표 중고역 오차(dB)</h2><p>1–3.2kHz의 유효 1/6옥타브 대역, 동일 마스크·동일 기준 레벨의 5초 평균 절댓값입니다. 작을수록 KM184에 가까운 대역 에너지지만, 어택·감쇠나 청감의 전부를 나타내지는 않습니다.</p><div class="table-wrap"><table><thead><tr><th>기기·주법</th><th>유효 창</th><th>기존</th><th>전체 감쇠</th><th>잔차 기반</th><th>보완단만 해당 주법 제외</th></tr></thead><tbody id="scores"></tbody></table></div>
<p class="note">잔차 기반 후보는 같은 10월 자료의 주법별 중앙값으로 설계해 같은 세션에서 점검했습니다. 마지막 열은 보완단의 계수만 해당 주법을 빼고 다시 정한 결과입니다. 기존 필터 자체는 10월 자료에 노출되어 있으므로 독립 성능 점수가 아닙니다. 퍼커션 S21은 유효 창 2개뿐입니다. 재생 클립은 모든 버전에 같은 기준 레벨과 공통 안전 배율을 적용했으며 배포 출력 게인은 아닙니다. 계수는 48kHz SOS로 제공하며, 오프라인 전체 파일 시험에서는 필터 뒤에 우선 −3dB 출력 감쇠를 두세요. 전체 파일의 true peak는 아직 확인하지 않았습니다. <a href="upper-mid-supplement-browser.json">계수·응답·점수·클립 목록</a>.</p>
</main><script>const data=__DATA__;const labels={km184:'KM184 기준',raw:'기기 원본',baseline:'기존 필터',broad_cut:'1–2kHz 전체 감쇠',shaped:'잔차 기반 보완'};const colors={baseline:'#718692',broad_cut:'#d46d37',shaped:'#087e8b'};let group='open_notes',device='iphone',variant='shaped',audio=null,position=0;const audios={};const seek=document.getElementById('seek');function choice(){return data.clips.find(c=>c.group===group&&c.device===device)}function stop(){if(audio){audio.pause();position=audio.currentTime||position;audio=null}}function sync(){if(audio&&!audio.paused)position=audio.currentTime;seek.value=position;document.getElementById('time').textContent=position.toFixed(1)+' / 5.0초';document.querySelectorAll('.cursor').forEach(c=>c.style.left=(position/5*100)+'%');if(audio&&!audio.paused)requestAnimationFrame(sync)}function play(which,at){const same=audio===audios[which]&&!audio.paused;stop();variant=which;position=at===undefined?position:at;if(same&&at===undefined){sync();return}const a=audios[which];a.currentTime=Math.min(4.98,position);audio=a;a.play().catch(()=>{});sync()}function graph(){let s='<rect width="850" height="260" fill="white"/>';const fs=data.response_hz,x=f=>55+Math.log(f/300)/Math.log(6000/300)*750,y=v=>130-v*18;for(const v of [-5,0,5])s+=`<line x1="55" x2="805" y1="${y(v)}" y2="${y(v)}" stroke="${v===0?'#778a90':'#e2e9eb'}"/><text x="12" y="${y(v)+4}" font-size="13">${v>0?'+':''}${v}</text>`;for(const f of [300,500,1000,1500,2000,3000,6000])s+=`<text x="${x(f)}" y="245" text-anchor="middle" font-size="12">${f>=1000?f/1000+'k':f}</text>`;for(const v of ['baseline','broad_cut','shaped']){const ys=data.models[device].response_db[v];s+=`<polyline points="${fs.map((f,i)=>x(f)+','+y(ys[i])).join(' ')}" fill="none" stroke="${colors[v]}" stroke-width="${v==='shaped'?3:2}"/>`;s+=`<text x="${v==='baseline'?85:v==='broad_cut'?335:590}" y="20" fill="${colors[v]}" font-size="15">${labels[v]}</text>`}document.getElementById('response').innerHTML=s}function scores(){const names={open_notes:'개방현 단음',complex:'복합 화음',percussion:'퍼커션'};let html='';for(const d of ['iphone','s21'])for(const g of Object.keys(names)){const x=data.summary[d].groups[g];html+=`<tr><td>${d.toUpperCase()} · ${names[g]}</td><td>${x.windows}</td><td>${x.baseline.toFixed(2)}</td><td>${x.broad_cut.toFixed(2)}</td><td><b>${x.shaped.toFixed(2)}</b></td><td>${x.shaped_loo.toFixed(2)}</td></tr>`}document.getElementById('scores').innerHTML=html}function render(preserve=false){stop();if(!preserve)position=0;const c=choice();document.querySelectorAll('#groups button').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.group===group)));document.querySelectorAll('#devices button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.device===device)));document.getElementById('selection').textContent=c.label+' · KM184 '+c.start_s+'–'+(c.start_s+5)+'초 · '+device.toUpperCase()+' · 동일 시각의 다섯 버전';const box=document.getElementById('versions');box.replaceChildren();for(const key of ['km184','raw','baseline','broad_cut','shaped']){const m=c.media[key],card=document.createElement('div');card.className='version';card.innerHTML=`<h3>${labels[key]}</h3><div class="image-row"><div class="spec" data-key="${key}"><img src="${m.spectrogram}" alt="${labels[key]} 스펙트로그램"><span class="cursor"></span></div><div class="spec" data-key="${key}">${m.residual?`<img src="${m.residual}" alt="${labels[key]}와 KM184의 잔차 지도">`:'<div style="padding:25px;line-height:1.5">기준 녹음</div>'}<span class="cursor"></span></div></div><div class="axis"><span>0초</span><span>1초</span><span>2초</span><span>3초</span><span>4초</span><span>5초</span></div><button type="button" data-play="${key}">${labels[key]} 재생</button>`;box.append(card);audios[key]=new Audio(m.audio);audios[key].onended=()=>{audio=null;position=5;sync()}}box.querySelectorAll('[data-play]').forEach(b=>b.onclick=()=>play(b.dataset.play));box.querySelectorAll('.spec').forEach(el=>el.onclick=e=>{const r=el.getBoundingClientRect();play(el.dataset.key,Math.max(0,Math.min(4.98,(e.clientX-r.left)/r.width*5)))});graph();sync()}document.getElementById('groups').innerHTML=[['open_notes','개방현 단음'],['complex','복합 화음'],['percussion','퍼커션']].map(([g,n])=>`<button type="button" data-group="${g}">${n}</button>`).join('');document.querySelectorAll('#groups button').forEach(b=>b.onclick=()=>{group=b.dataset.group;render()});document.getElementById('devices').innerHTML=['iphone','s21'].map(k=>`<button type="button" data-device="${k}">${k.toUpperCase()}</button>`).join('');document.querySelectorAll('#devices button').forEach(b=>b.onclick=()=>{device=b.dataset.device;render(true)});seek.oninput=()=>{stop();position=Number(seek.value);sync()};document.getElementById('toggle').onclick=()=>play(variant);scores();render()</script></html>'''
page = page.replace('__DATA__', data)
(PUBLIC / 'upper-mid-supplement.html').write_text(page)
print(PUBLIC / 'upper-mid-supplement.html')
